// same payload the Wave Farmer publishes → the Dungeon Farmer panel reads it on its pages
function hubPublishSkin() {
  try {
    const id = hubGetTheme(), th = VFB_THEMES.find(x => x.id === id) || VFB_THEMES[0];
    if (id === 'atomic') { localStorage.setItem('sf_theme_skin', JSON.stringify({ id: 'atomic' })); return; }
    const kf = (vfbThemeCSS() || '').match(/@keyframes\s+[\w-]+\s*\{(?:[^{}]|\{[^{}]*\})*\}/g) || [];
    localStorage.setItem('sf_theme_skin', JSON.stringify({
      id: th.id, dock: (th.id === 'lite') ? 'ATOMIC' : th.dock,
      logo: vfbThemeLogo(th.id, 38, 'dg'),
      css: kf.join('\n') + '\n' + dgThemeCSS(),
    }));
  } catch (e) { /* cosmetic only */ }
}
let hubFx = null;
function hubApplyTheme(panel, animate) {
  try {
    if (!document.getElementById('vfb-themes')) { const st = document.createElement('style'); st.id = 'vfb-themes'; st.textContent = vfbThemeCSS(); document.head.appendChild(st); }
    if (!document.getElementById('sh-themes')) { const st = document.createElement('style'); st.id = 'sh-themes'; st.textContent = dgThemeCSS(); document.head.appendChild(st); }
    const id = hubGetTheme(), th = VFB_THEMES.find(x => x.id === id) || VFB_THEMES[0], root = document.documentElement;
    for (const el of [root, panel]) { if (th.id === 'atomic') el.removeAttribute('data-sh-theme'); else el.setAttribute('data-sh-theme', th.id); }
    let lite = false; try { lite = localStorage.getItem('sf_fx_mode') === 'lite'; } catch (e) { }
    root.classList.toggle('sf-lite', lite);
    if (!hubFx || hubFx._tid !== th.id) {
      if (hubFx) { vfbDisposeFx(hubFx); hubFx.remove(); hubFx = null; }
      hubFx = vfbMakeFx(th.id, 'sh-fx'); if (hubFx) hubFx._tid = th.id;
    }
    if (hubFx && hubFx.parentNode !== panel) panel.appendChild(hubFx);
    const t = panel.querySelector('.sh-title');
    if (t) t.innerHTML = ((th.id === 'atomic' || th.id === 'lite') ? 'ATOMIC' : th.dock) + ' <span>Version History</span>';
    const brand = panel.querySelector('.sh-brand');
    if (brand && (brand.dataset.hubT || 'atomic') !== th.id) { vfbSwapLogo(brand, vfbThemeLogo(th.id, 38, 'hub')); brand.dataset.hubT = th.id; }
    if (animate) { panel.classList.remove('vfb-swap'); void panel.offsetWidth; panel.classList.add('vfb-swap'); setTimeout(() => panel.classList.remove('vfb-swap'), 500); }
    hubPublishSkin();
  } catch (e) { /* cosmetic only */ }
}
