// v6.12.4 — battle.php shadow extract. The live button is
// <button id="extract-shadow-btn" class="btn btn-rise-dead">☠ Extraction</button>
// and the page POSTs action=extract_shadow to battle.php?id=… (JSON {ok, shadow}).
(function atomicShadowExtractBoot() {
  if (window.__ATOMIC_EXTRACT_BOOT__) return;
  window.__ATOMIC_EXTRACT_BOOT__ = true;
  const DONE = 'atomic_extract_done';
  const doneSet = () => {
    try { return new Set(JSON.parse(sessionStorage.getItem(DONE) || '[]')); }
    catch (e) { return new Set(); }
  };
  const markDone = (id) => {
    const s = doneSet();
    s.add(String(id));
    try { sessionStorage.setItem(DONE, JSON.stringify([...s].slice(-80))); } catch (e) {}
  };
  let busy = false;
  async function claimOpenExtract() {
    if (busy) return;
    const btn = document.getElementById('extract-shadow-btn');
    if (!btn || btn.disabled || btn.dataset.atomicClaim === '1') return;
    const id = new URLSearchParams(location.search).get('id') || '';
    if (id && doneSet().has(id)) { btn.dataset.atomicClaim = '1'; btn.disabled = true; return; }
    busy = true;
    btn.dataset.atomicClaim = '1';
    const url = location.origin + location.pathname + location.search;
    try {
      const res = await fetch(url, {
        method: 'POST',
        credentials: 'same-origin',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' },
        body: 'action=extract_shadow',
      });
      const raw = await res.text();
      let data = null;
      try { data = JSON.parse(raw); } catch (e) {}
      const msg = (data && (data.message || data.msg)) || '';
      const shadow = data && data.shadow;
      const ok = !!(data && (data.ok === true || data.ok === 1 || (shadow && shadow.name && data.ok !== false)));
      const already = /already|taken|no longer|cannot|can't extract|no shadow|not extract/i.test(msg + ' ' + raw.slice(0, 180));
      if (ok || already) {
        if (id) markDone(id);
        btn.disabled = true;
        console.log('[ATOMIC] extract', ok ? ((shadow && shadow.name) || 'ok') : 'already');
      } else {
        delete btn.dataset.atomicClaim;
      }
    } catch (e) {
      delete btn.dataset.atomicClaim;
      console.warn('[ATOMIC] extract failed', e);
    } finally {
      busy = false;
    }
  }
  const kick = () => { if (document.getElementById('extract-shadow-btn')) claimOpenExtract(); };
  setInterval(kick, 1200);
  new MutationObserver(kick).observe(document.documentElement, { childList: true, subtree: true });
  kick();
})();

