  // Slash buttons show stamina with the shared Asterion switch (×2.5).
  function paintBattleAsterionCosts() {
    if (!useBetterAttackButtons) return;
    const on = readBossAsterion();
    document.querySelectorAll(".attack-btn").forEach((btn) => {
      const costEl = btn.querySelector(".skill-cost");
      if (costEl) {
        if (!costEl.dataset.baseText) costEl.dataset.baseText = costEl.textContent.trim();
        const text = costEl.dataset.baseText;
        const match = text.match(/(\d+)\s*MP\s*\/\s*(\d+)\s*STAM/i);
        if (!match) return;
        const mp = match[1];
        const baseStam = Number(match[2]);
        const finalStam = on ? baseStam * 2.5 : baseStam;
        costEl.textContent = `${mp} MP / ${finalStam} STAM`;
        return;
      }
      if (!btn.dataset.baseText) btn.dataset.baseText = btn.textContent.trim();
      const text = btn.dataset.baseText;
      const match = text.match(/\((\d+)\s*STAMINA\)/i);
      const baseCost = match ? Number(match[1]) : 1;
      const finalCost = on ? baseCost * 2.5 : baseCost;
      const name = text.replace(/\s*\(.*?\)\s*/, "");
      btn.textContent = `${name} (${finalCost})`;
    });
    try { if (typeof updateAttackButtons === "function") updateAttackButtons(); } catch (e) {}
  }
  paintBattleAsterionCosts();
  window.addEventListener("atomic-asterion", paintBattleAsterionCosts);
