    const root = crystalRoot();
    const sels = root ? [...root.querySelectorAll('select[data-gear]')] : [];
    const wants = sels
      .filter((sel) => sel.getAttribute('data-gear') === key)
      .sort((a, b) => Number(a.getAttribute('data-slot')) - Number(b.getAttribute('data-slot')))
      .map((sel) => sel.value || '');
    const picked = [];
    wants.forEach((id) => { if (id && picked.indexOf(id) < 0) picked.push(id); });
    if (picked.length > 3) picked.length = 3;
    const current = gear0.slots.map((s) => s.crystalId).filter(Boolean);
    if (picked.length === current.length && picked.every((id) => current.indexOf(id) >= 0)) {
      if (!picked.length) setStatus('Pick at least one crystal.');
      return;
    }
    state.busy = true;
    setStatus(picked.length ? ('Equipping ' + picked.length + '…') : 'Clearing this item…');
    let doc = state.doc;
