    // Sets the html classes for the current device: sf-pc / sf-phone / sf-compact (phone, size S) / sf-lite (FX)
    function applyDeviceClasses() {
        const d = deviceMode(), h = document.documentElement;
        h.classList.toggle('sf-pc', d === 'pc');
        h.classList.toggle('sf-phone', d === 'phone');
        h.classList.toggle('sf-compact', d === 'phone' && localStorage.getItem('sf_size') !== 'roomy');
        h.classList.toggle('sf-lite', fxIsLite());
    }
    applyDeviceClasses();

    // AUTO → PC → PHONE → AUTO. Resets FX to the new device's default so the look matches the device.
    function cycleDevice() {
        const order = ['auto', 'pc', 'phone'];
        const next = order[(order.indexOf(deviceChoice()) + 1) % order.length];
        localStorage.setItem(DEVICE_KEY, next);
        localStorage.removeItem(FX_KEY);
        applyDeviceClasses();
        renderGUI();
        showToast(`Device mode: ${next === 'auto' ? 'AUTO (detected ' + deviceMode().toUpperCase() + ')' : next.toUpperCase()}`, 'info', 2200);
    }


    // ================================================================
    // FULL GUI — shown on all matched pages
