    launchModal.style.cssText = modalBaseCSS + "width:380px;";
    document.body.appendChild(launchModal);
    [attackModal, lootModal, bossModal, generalModal, attackConfigModal, launchModal].forEach(m => {
        m.classList.add('sh-modal');
        ['wheel', 'touchmove'].forEach(ev => m.addEventListener(ev, e => e.stopPropagation(), { passive: true }));
    });

    /* ======================
       LOGIC & RENDERING
    ====================== */

    function addLog(msg, persist = true) {
        try {
            logHistory.push({
                message: msg,
                timestamp: new Date().toISOString()
            });

            if (logHistory.length > MAX_LOGS) {
                logHistory.splice(0, logHistory.length - MAX_LOGS);
            }

            if (persist) {
                persistLogs();
            }
            //if (logHistory.length > 80) logHistory.shift();
            renderLogs();
        } catch (e) {
            if (persist) {
                addLogToStorage(msg);
            }
        }
    }

    function clearLogs() {
        logHistory = [];
        persistLogs();
        renderLogs();
    }

    function persistLogs() {
        localStorage.setItem(LOG_HISTORY_KEY, JSON.stringify(logHistory));
    }
    function loadLogs() {
        const stored = localStorage.getItem(LOG_HISTORY_KEY);
        if (!stored) return;
        try {
            const parsed = JSON.parse(stored);
            if (Array.isArray(parsed)) {
                logHistory = parsed;
            }
        } catch (e) {
            console.error("Error parsing stored logs:", e);
        }
    }
    function addLogToStorage(msg) {
        const stored = localStorage.getItem(LOG_HISTORY_KEY);
        if (!stored) return;
        try {
            const parsed = JSON.parse(stored);
            parsed.push(msg);
            localStorage.setItem(LOG_HISTORY_KEY, JSON.stringify(parsed));
        } catch (e) {
            console.error("Error parsing stored logs:", e);
        }
    }


    function applyLogVisibility() {
        const show = settings.showActionLog !== false;
        logBox.style.display = show ? '' : 'none';
        const clr = document.getElementById('clearLogsBtn');
        if (clr) clr.style.display = show ? '' : 'none';
        if (show) renderLogs();
    }

    const LOG_DOM_MAX = 120;
    let logRaf = 0;
    function renderLogs() {
        if (!logBox || settings.showActionLog === false) return;
        if (logRaf) return;
        logRaf = requestAnimationFrame(() => {
            logRaf = 0;
            const stick = logBox.scrollHeight - logBox.scrollTop - logBox.clientHeight < 40;
            const frag = document.createDocumentFragment();
            let rows = [];
            for (let i = logHistory.length - 1; i >= 0 && rows.length < LOG_DOM_MAX; i--) {
                const m = String(logHistory[i].message);
                const cls = /🚫|❌|⛔/.test(m) ? 'bad' : /⚠️|🔋|💊/.test(m) ? 'warn' : /✅|🗡️|💰|💀|🌟|⚡/.test(m) ? 'good' : '';
                if (logFilter !== 'all' && cls !== logFilter) continue;
                const div = document.createElement('div');
                div.className = 'sh-log-row ' + cls;
                div.innerHTML = m;
                rows.push(div);
            }
            for (let i = rows.length - 1; i >= 0; i--) frag.appendChild(rows[i]);
            logBox.replaceChildren(frag);
            if (stick) logBox.scrollTop = logBox.scrollHeight;
        });
    }

    function updateUiTextOnly() {
        const uiHp = document.getElementById('ui-hp');
        const uiStam = document.getElementById('ui-stamina');
        const uiExp = document.getElementById('ui-exp');
        const uiPots = document.getElementById('ui-pots');

        if (uiHp) uiHp.textContent = lastKnownHp;
        if (uiStam) uiStam.textContent = currentStamina;
        if (uiExp) uiExp.textContent = lastKnownExp;
        if (uiPots) uiPots.textContent = formatRefillCounter();
        updateMissionStrip();
    }

    function updateMissionStrip() {
        const el = document.getElementById('sf-clock');
        if (!el) return;
        const ms = Date.now() - sessionStart;
        const hrs = Math.max(ms / 3600000, 1 / 3600);
        const rate = v => (ms < 20000 || !v) ? '—' : fmtCompact(Math.round(v / hrs));
        const t = fmtDuration(ms);
        if (el.textContent !== t) el.textContent = t;
        document.getElementById('sf-expph').textContent = rate(totalExpLooted);
        document.getElementById('sf-goldph').textContent = rate(totalGoldLooted);
        document.getElementById('sf-lootph').textContent = rate(monstersLooted + bossesLooted);
        const bs = document.getElementById('sf-bar-st'), be = document.getElementById('sf-bar-exp');
        if (bs) bs.style.width = (playerStats.maxStamina > 0 ? Math.min(100, currentStamina / playerStats.maxStamina * 100) : 0).toFixed(1) + '%';
        if (be) be.style.width = Math.min(100, Math.max(0, currentExpRatio * 100)).toFixed(1) + '%';
        const eta = document.getElementById('sf-eta');
        if (eta) {
            const perHr = ms >= 20000 ? totalExpLooted / hrs : 0;
            const left = maxExpRaw - currentExpRaw;
            let txt = '—';
            if (perHr > 0 && left > 0) {
                const m = Math.round(left / perHr * 60);
                txt = '~' + (m < 60 ? m + 'm' : m >= 2880 ? '48h+' : Math.floor(m / 60) + 'h ' + (m % 60) + 'm');
            }
            eta.textContent = 'LEVEL-UP ETA (from loot rate): ' + txt;
        }
        const pg = document.getElementById('sf-ping');
        if (pg) {
            const v = Math.round(NET.ema);
            pg.textContent = v ? `${v}ms · ${netRpm()}/min` : '— ms';
            pg.className = 'sf-ping ' + (!v ? '' : v < 400 ? 'ok' : v < 1200 ? 'mid' : 'bad');
        }
    }
    setInterval(() => { if (document.hidden) return; try { updateMissionStrip(); } catch (e) { } }, 1000);

    function formatExpPercent(ratio) {
        return (ratio * 100).toFixed(1) + "%";
    }

    function applyStatsSnapshot(stats, {
        syncHp = true,
        syncStamina = true,
        syncExp = true,
        refreshUi = true
    } = {}) {
        if (!stats) return false;

        if (syncHp && stats.hp !== null) lastKnownHp = stats.hp;
        if (syncStamina && stats.stamina !== null) currentStamina = stats.stamina;
        if (syncExp && stats.exp) {
            currentExpRaw = stats.exp.current;
            maxExpRaw = stats.exp.max;
            currentExpRatio = stats.exp.ratio;
            lastKnownExp = formatExpPercent(stats.exp.ratio);
        }

        if (refreshUi) updateUiTextOnly();
        return true;
    }

    async function applyExpGain(expGained, levelUpLogMessage = '') {
        if (!expGained || expGained <= 0) return;

        if (maxExpRaw <= 0) {
            const refreshed = await getPlayerStatsFromWave();
            applyStatsSnapshot(refreshed);
            return;
        }

        currentExpRaw += expGained;
        if (currentExpRaw >= maxExpRaw) {
            if (levelUpLogMessage) addLog(levelUpLogMessage);
            const refreshed = await getPlayerStatsFromWave();
            applyStatsSnapshot(refreshed);
            return;
        }

        currentExpRatio = currentExpRaw / maxExpRaw;
        lastKnownExp = formatExpPercent(currentExpRatio);
        updateUiTextOnly();
    }

    function buildFormBody(paramsObj) {
        return new URLSearchParams(paramsObj).toString();
    }

    function postForm(url, paramsObj) {
        return safeFetch(url, {
            method: 'POST',
            headers: FORM_HEADERS,
            body: buildFormBody(paramsObj),
            credentials: 'same-origin'
        });
    }

    function setStatus(newStatus) {
        currentStatus = newStatus;
        renderGUI();
    }

    function stopAutomation(reason = '', stopLoop = false) {
        running = false;
        sessionStorage.setItem(AUTO_RUNNING_KEY, 'false');
        if (stopLoop || !settings.autoLoop) {
            stopRun();
            sessionStorage.setItem(LOOP_KEY, 'false');
            setStatus('STOPPED');
            logRunSummary();
        }
        if (stopLoop && settings.autoLoop) {
            addLog("🚫 [STOPPED] Looping stopped.");
        }
        if (reason) {
            addLog(`🚫 [STOPPED] ${reason}`);
            if (!/Stopped by user/i.test(reason)) {
                const plain = reason.replace(/^[^\w]+/u, '').split('\n')[0].slice(0, 160);
                const ok = /complete|finished|no targets left|no lootable/i.test(reason);
                const bad = /error|fail|mismatch|exceeded|insufficient/i.test(reason);
                showToast(plain, ok ? 'success' : bad ? 'error' : 'warn', 6000);
                if (ok) playAlert('done');
            }
        }
    }

    function resetSession() {
        resetRunPotions(true);   // permanent potion limits start from 0 again only here
        staminaRefillsUsed = 0;
        manaPotionsUsed = 0;
        largePotionsDepleted = false;
        manaPotionsDepleted = false;
        bossesLooted = 0;
        monstersLooted = 0;
        totalExpLooted = 0;
        totalGoldLooted = 0;
        lootTracker = {};
        sessionStart = Date.now();
        persistSessionStats();
        updateStatsModal();
        updateUiTextOnly();
        addLog("🔄 Session stats reset. Potion limits reset - auto potions are available again.");
    }

