            settings.soundAlerts = document.getElementById('gs_chk_sound').checked;
            settings.keepAwake = document.getElementById('gs_chk_awake').checked;
            settings.autoStopMin = Math.max(0, parseIntStrict(document.getElementById('gs_in_autostop').value, 0));
            settings.staminaFullAlert = document.getElementById('gs_chk_stamfull').checked;
            settings.stopOnManaLimit = document.getElementById('gs_chk_stop_mana').checked;
            settings.limitAlerts = document.getElementById('gs_chk_limit_alert').checked;
            settings.potionPreflight = document.getElementById('gs_chk_preflight').checked;
            updatePotionHud();
            settings.liveRefresh = document.getElementById('gs_chk_liverefresh').checked;
            settings.vibrate = document.getElementById('gs_chk_vibrate').checked;
            pvpNodesFellBack = false; pvpEmptyScans = 0;
            try { if (settings.soundAlerts && 'Notification' in window && Notification.permission === 'default') Notification.requestPermission().catch(() => { }); } catch (e) { }
            syncRunExtras();
            pvpInstanceId = null; pvpActiveNodes = [];   // re-read the node list on the next check
            const tb = document.getElementById('ui-turbo'); if (tb) tb.textContent = '⚡ ×' + getTurbo();
            persistAllSettings();
