    bindNum('gw-gap', (v) => (S.attackGapMs = Math.max(MIN_GAP_MS, v || MIN_GAP_MS)));
    bindNum('gw-poll', (v) => (S.pollSec = Math.max(5, v || 15)));
    bindNum('gw-permon', (v) => (S.maxStamPerMonster = v));
    bindNum('gw-stopstam', (v) => (S.stopAfterStamina = v));
