    if (!keys.length) { setStatus('Tick at least one monster under Quick Add Targets first.'); return 0; }
    const enabled = $('gw-addenabled').value === '1';
    const mode = $('gw-addmode').value === 'cap' ? 'cap' : 'min';
    const min = Math.max(0, num($('gw-addmin').value));
