        log(`Stopped: ${reason} | ${fmtC(run.total)} / ${fmtC(cap)} | ${run.hits} hits, ${run.casts} buff casts, ${used.mana} mana potions`, reason === 'damage cap reached' || reason === 'boss killed' ? 'ok' : 'warn');
