  /* ---- compact number helpers for the session log ---- */
  function parseCompact(s) {
    var m = String(s).replace(/,/g, "").match(/([\d.]+)\s*([KMBT]?)/i);
    if (!m) return 0;
    var mult = { "": 1, K: 1e3, M: 1e6, B: 1e9, T: 1e12 }[m[2].toUpperCase()];
    return parseFloat(m[1]) * mult;
  }
