      '<div class="sm-head"><span>[ MARTIAL SCROLL <i class="mx-cjk">武林</i> ]</span><button type="button" class="sm-x" aria-label="Close">✕</button></div>' +
      '<div class="sm-me" id="sm-me"></div>' +
      '<div class="sm-session" id="sm-session"></div>' +
      '<div class="sm-searchrow"><input id="sm-search" type="text" autocomplete="off" placeholder="Name a hall to visit…  (Enter = go, Esc = close)"></div>' +
      '<div id="sm-recent"></div>' +
      '<div class="sm-grid" id="sm-grid"></div>' +
      '<div class="sm-foot"><span class="sm-hint"><kbd>M</kbd> scroll · <kbd>/</kbd> search · <kbd>G</kbd> then key = travel · <kbd>?</kbd> manual</span>' +
      '<span class="sm-btns"><button type="button" id="sm-help">Manual</button><button type="button" id="sm-tl">Techniques</button><button type="button" id="sm-set">Settings</button></span></div>' +
      '<div class="sm-settings" id="sm-settings"></div><div class="sm-tools" id="sm-tools"></div></div>';
    document.body.appendChild(menuEl);

    var grid = $("#sm-grid", menuEl);
    NAV.forEach(function (c) {
      var d = document.createElement("div");
      d.className = "sm-cat";
      d.innerHTML = '<div class="sm-ct"><span>' + c.icon + "</span> " + c.cat + "</div>";
      c.items.forEach(function (i) { d.appendChild(menuItem(i)); });
      grid.appendChild(d);
    });
    menuEl.addEventListener("click", function (e) { if (e.target === menuEl) closeMenu(); });
    $(".sm-x", menuEl).addEventListener("click", closeMenu);
    $("#sm-help", menuEl).addEventListener("click", function () { closeMenu(); openHelp(); });
    $("#sm-set", menuEl).addEventListener("click", function () { $("#sm-tools", menuEl).classList.remove("open"); $("#sm-settings", menuEl).classList.toggle("open"); renderSettings(); });
    $("#sm-tl", menuEl).addEventListener("click", function () { $("#sm-settings", menuEl).classList.remove("open"); $("#sm-tools", menuEl).classList.toggle("open"); renderTools(); });
    var inp = $("#sm-search", menuEl);
    inp.addEventListener("input", filterMenu);
    inp.addEventListener("keydown", function (e) {
      if (e.key === "Enter") { var f = visibleItems()[0]; if (f) f.click(); }
      else if (e.key === "ArrowDown") { var v = visibleItems(); if (v[0]) { v[0].focus(); e.preventDefault(); } }
    });
