  function helpOpen() { return !!(helpEl && helpEl.classList.contains("open")); }

  /* ---- Central hotkeys ---- */
  var chordT = null, chordEl = null;
  function showChord(on) {
    if (!chordEl) {
      chordEl = document.createElement("div");
      chordEl.id = "sys-chord";
      chordEl.innerHTML = "<b>[ TRAVEL ]</b> <kbd>1</kbd> Realm 1 · <kbd>2</kbd> Realm 2 · <kbd>G</kbd> All realms · <kbd>H</kbd> Hall · <kbd>I</kbd> Pouch · <kbd>P</kbd> Arena · <kbd>S</kbd> Legion · <kbd>M</kbd> Merchant · <kbd>B</kbd> Smith · <kbd>A</kbd> Legends · <kbd>W</kbd> Ranking";
      document.body.appendChild(chordEl);
    }
    chordEl.classList.toggle("on", !!on);
  }
  function hotkeys() {
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape") {
        if (autoOpen()) { autoClose(); return; }
        if (botIsOpen()) { botClose(); return; }
        if (menuOpen()) { closeMenu(); return; }
        if (helpOpen()) { closeHelp(); return; }
        var cp = $("#gcw_panel.gcw-open"); if (cp && $("#gcw_close")) $("#gcw_close").click();
        return;
      }
      var t0 = (e.composedPath && e.composedPath()[0]) || e.target;
      var tg = t0 && t0.tagName;
      var typing = /INPUT|TEXTAREA|SELECT/.test(tg) || (t0 && t0.isContentEditable);
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k") { e.preventDefault(); openMenu(true); return; }
      if (typing || e.ctrlKey || e.metaKey || e.altKey || !setting("keys")) return;
      if (menuOpen() || helpOpen() || botIsOpen() || autoOpen()) return;
      var k = e.key;
      if (chordT) {
        clearTimeout(chordT); chordT = null; showChord(false);
        var lk = k.toLowerCase();
        var id = lk === "g" ? "gall" : CHORDS[lk] || (lk === "?" ? "guide" : null);
        if (id) { e.preventDefault(); goTo(id); }
        return;
      }
      if (k >= "1" && k <= "9") { var s = $('.sys-slot[data-hot="' + k + '"]'); if (s) s.click(); return; }
      var l = k.toLowerCase();
      if (l === "g") { e.preventDefault(); showChord(true); chordT = setTimeout(function () { chordT = null; showChord(false); }, 2200); }
      else if (l === "m") { e.preventDefault(); openMenu(); }
      else if (l === "s") { e.preventDefault(); botOpen(); }
      else if (l === "a") { e.preventDefault(); autoToggle(); }
      else if (k === "/") { e.preventDefault(); openMenu(true); }
      else if (k === "?") { e.preventDefault(); openHelp(); }
      else if (l === "c") { var t = $("#gcw_toggle"); if (t) { e.preventDefault(); t.click(); } }
      else if (l === "t") { window.scrollTo({ top: 0, behavior: "smooth" }); }
    });
    // our menu replaces the classic side drawer
    document.addEventListener("click", function (e) {
      var t = e.target.closest && e.target.closest("#nav_fab");
      if (t && !classicMode) { e.preventDefault(); e.stopImmediatePropagation(); openMenu(); }
    }, true);
  }

  /* ---- misc HUD bits ---- */
  var TIPS = {
    stamina: "Qi (stamina) – spent when you strike. Refills every hour or with elixirs (quick-bar).",
    gold: "Silver – currency for merchants, smiths and upgrades.",
    gems: "Jade – precious currency.",
    server: "Heavenly hour – events and resets follow this clock.",
    buffs: "Your active elixir effects."
  };
  function hudExtras() {
    $$(".gtb-stat,.gtb-buffs-btn").forEach(function (s) {
      var l = $(".gtb-label", s);
      var k = l ? l.textContent.trim().toLowerCase() : "";
      if (TIPS[k] && !s.title) s.title = TIPS[k];
    });
    var lvl = $(".gtb-level"); if (lvl && !lvl.title) lvl.title = "Your level. Open the Martial Scroll (M) to see today's progress.";
    // stamina meter under the stat chip
    var st = staminaInfo(), box = $("#stamina_span") && $("#stamina_span").closest(".gtb-stat");
    if (st && st.max && box && !$(".sys-sbar", box)) {
      var p = Math.min(100, Math.round(st.cur / st.max * 100));
      var bar = document.createElement("i");
      bar.className = "sys-sbar" + (p < 10 ? " low" : "");
      bar.innerHTML = '<u style="width:' + p + '%"></u>';
      box.appendChild(bar);
    }
    // scroll-to-top button
    if (!$("#sys-top")) {
      var b = document.createElement("button");
      b.id = "sys-top"; b.type = "button"; b.title = "Back to the peak (T)"; b.textContent = "▲";
      b.addEventListener("click", function () { window.scrollTo({ top: 0, behavior: "smooth" }); });
      document.body.appendChild(b);
      addEventListener("scroll", function () { b.classList.toggle("on", scrollY > 500); }, { passive: true });
    }
    // chat polish
    var inp = $("#gcw_input"); if (inp) inp.placeholder = "Send a whisper…";
    var tg = $("#gcw_toggle"); if (tg) tg.title = "Jianghu whispers (C)";
  }

  /* ------------------------------------------------------------------ *
   * 9c) v4: sound, SYSTEM bot, daily quests, chat badge
   * ------------------------------------------------------------------ */
  var AC = null, gestured = false;
  ["pointerdown", "keydown", "touchstart"].forEach(function (ev) {
    addEventListener(ev, function () { gestured = true; }, { once: true, passive: true, capture: true });
  });
  function tone(f, d, type, v, delay) {
    if (!setting("sound") || !gestured) return;
    try {
      AC = AC || new (window.AudioContext || window.webkitAudioContext)();
      if (AC.state === "suspended") AC.resume();
      var o = AC.createOscillator(), g = AC.createGain(), t0 = AC.currentTime + (delay || 0);
      o.type = type || "sine"; o.frequency.setValueAtTime(f, t0);
      g.gain.setValueAtTime(v || 0.04, t0); g.gain.exponentialRampToValueAtTime(0.0001, t0 + d);
      o.connect(g); g.connect(AC.destination); o.start(t0); o.stop(t0 + d + 0.02);
    } catch (e) {}
  }
  var sfx = {
    ding: function () { tone(988, .18, "sine", .05); tone(1319, .34, "sine", .05, .11); },
    pop:  function () { tone(660, .07, "triangle", .03); },
    warn: function () { tone(200, .22, "sawtooth", .03); tone(160, .3, "sawtooth", .03, .15); },
    up:   function () { [523, 659, 784, 1047].forEach(function (f, i) { tone(f, .24, "sine", .05, i * .11); }); }
  };

  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]; }); }
  function hhmm(t) { var d = new Date(t); return ("0" + d.getHours()).slice(-2) + ":" + ("0" + d.getMinutes()).slice(-2); }
  function bar(p) { p = Math.max(0, Math.min(100, p)); return '<i class="sb-meter"><u style="width:' + p + '%"></u></i>'; }
  function row(k, v) { return '<div class="sb-row"><span>' + k + "</span><b>" + v + "</b></div>"; }
  function isPhone() { return window.matchMedia && matchMedia("(max-width:720px)").matches; }

  /* ---- potions helper ---- */
  function potionList() {
    return $$("#battleDrawer .potion-card").map(function (c) {
      var n = (($(".potion-name span", c) || {}).textContent || "Potion").trim();
      var q = $(".potion-qty-left", c);
      return { c: c, name: n, t: potionType(n), q: q ? num(q.textContent) : 0 };
    });
  }

  /* ---- daily quests (tracked locally in this browser) ---- */
  var QUESTS = [
    { id: "gate",   name: "Enter a Secret Realm",   hint: "visit any Secret Realm (press G then 1 or 2)",       re: /gates\.php|active_wave|olympus|dungeon_info|world_map|guild_dungeon/i },
    { id: "gear",   name: "Maintain your arsenal",  hint: "open the Pouch, Master Smith, Spirit Beasts or Spirit Stones", re: /inventory|blacksmith|pets|power_crystals/i },
    { id: "shop",   name: "Visit the market",       hint: "Merchant, Black Market, Weekly Bargains or the Mercenary Hall",   re: /merchant|weekly_deals|adventurers_guild/i },
    { id: "potion", name: "Take an elixir",         hint: "tap an elixir twice on the quick-bar",        re: null }
  ];
  var TITLES = [[30, "[Heavenly Demon]"], [14, "[Unyielding Blade]"], [7, "[Sect Elite]"], [3, "[Sect Disciple]"], [1, "[Initiate]"]];
  function titleFor(streak) { for (var i = 0; i < TITLES.length; i++) if (streak >= TITLES[i][0]) return TITLES[i][1]; return "[None]"; }
  function pad2(n) { return ("0" + n).slice(-2); }
  function today() { var d = new Date(); return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate()); }
  function dayBefore(s) { var p = s.split("-"), d = new Date(+p[0], +p[1] - 1, +p[2] - 1); return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate()); }
  function qState() {
    var s = null; try { s = JSON.parse(store.get("sysQ", "null")); } catch (e) {}
    if (!s || typeof s !== "object") s = { d: "", done: {}, streak: 0, lastFull: "", ann: "", missed: false };
    return s;
  }
  function qSave(s) { store.set("sysQ", JSON.stringify(s)); }
  function qRoll() {
    var s = qState(), t = today();
    if (s.d !== t) {
      var prevFull = Object.keys(s.done || {}).length >= QUESTS.length;
      s = { d: t, done: {}, streak: s.lastFull === dayBefore(t) ? s.streak : 0, lastFull: s.lastFull || "", ann: "", missed: !!(s.d && !prevFull) };
      qSave(s);
    }
    return s;
  }
  function qCount(s) { return QUESTS.filter(function (q) { return s.done[q.id]; }).length; }
  function qMark(id) {
    var s = qRoll();
    if (s.done[id]) return false;
    var q = QUESTS.filter(function (x) { return x.id === id; })[0];
    if (!q) return false;
    s.done[id] = 1;
    var n = qCount(s);
    var full = n >= QUESTS.length;
    if (full) { s.streak = (s.lastFull === dayBefore(s.d) ? s.streak : 0) + 1; s.lastFull = s.d; }
    qSave(s);
    sfx.ding();
    sysToast("<b>Well done!</b> Trial cleared: " + q.name + " (" + n + "/" + QUESTS.length + ")", "gold", 5200, "TRIAL CLEARED");
    botNote("Trial Cleared", "<b>Well done!</b> " + q.name + " &mdash; <b>" + n + "/" + QUESTS.length + "</b> done.", "gold");
    if (full) {
      setTimeout(function () {
        sfx.up();
        sysToast("Daily Cultivation complete.<br>Title: <b>" + titleFor(s.streak) + "</b> &middot; Streak <b>" + s.streak + "</b>", "gold", 6500, "DAILY CULTIVATION");
        botNote("Daily Cultivation", "All trials complete. Your foundation grows stronger.<br>Title: <b>" + titleFor(s.streak) + "</b> &middot; Streak: <b>" + s.streak + "</b> day" + (s.streak === 1 ? "" : "s") + ".", "gold");
      }, 900);
    }
    return true;
  }
  function qCheckPage() {
    qRoll();
    var p = location.pathname;
    QUESTS.forEach(function (q) { if (q.re && q.re.test(p)) qMark(q.id); });
  }
  function qText() {
    var s = qRoll(), h = '<div class="sb-sub">Daily Cultivation: Training of a Disciple</div>';
    QUESTS.forEach(function (q) {
      h += '<div class="sb-q' + (s.done[q.id] ? " ok" : "") + '"><span>' + (s.done[q.id] ? "☑" : "☐") + "</span><div><b>" + q.name + "</b><small>" + q.hint + "</small></div></div>";
    });
    h += row("Progress", qCount(s) + " / " + QUESTS.length) + row("Streak", s.streak + " day" + (s.streak === 1 ? "" : "s")) + row("Title", titleFor(s.streak));
    return h;
  }
  function pendingQuests() { var s = qRoll(); return QUESTS.filter(function (q) { return !s.done[q.id]; }); }

  /* ---- bot state + persistence ---- */
  var BOT_KEY = "sysBotLog";
  function botLoad() { try { return JSON.parse(store.get(BOT_KEY, "[]")); } catch (e) { return []; } }
  function botSave(a) { store.set(BOT_KEY, JSON.stringify(a.slice(-60))); }
  var botEl = null, botPend = null, botQ = [], botBusy = false;
  function botIsOpen() { return !!(botEl && botEl.classList.contains("open")); }

  function botBadge() {
    var n = parseInt(store.get("sysBotUnread", "0"), 10) || 0;
    $$(".sys-slot.orb .bdg").forEach(function (b) { b.textContent = n > 9 ? "9+" : n; b.classList.toggle("on", n > 0); });
    $$(".sys-slot.orb").forEach(function (b) { b.classList.toggle("ping", n > 0); });
  }
  function botRenderOne(m) {
    var log = $("#sb-log"); if (!log) return;
    var d = document.createElement("div");
    d.className = "sb-m " + m.who + (m.k ? " " + m.k : "");
    d.innerHTML = (m.who === "sys" ? '<span class="sb-tag">[ ' + esc(m.tag || "Dao") + " ]</span>" : "") +
      '<div class="sb-t">' + m.html + "</div><time>" + hhmm(m.t) + "</time>";
    log.appendChild(d);
    log.scrollTop = log.scrollHeight;
  }
  function botPush(m) {
    var a = botLoad(), last = a[a.length - 1];
    if (last && last.who === m.who && last.html === m.html && Date.now() - last.t < 8000) return;
    m.t = Date.now(); a.push(m); botSave(a);
    if (botEl) botRenderOne(m);
    if (!botIsOpen() && m.who !== "me") { store.set("sysBotUnread", String((parseInt(store.get("sysBotUnread", "0"), 10) || 0) + 1)); botBadge(); }
  }
  function botNote(tag, html, kind) { botPush({ who: "sys", tag: tag, html: html, k: kind || "" }); }
  function botNext() {
    var it = botQ.shift();
    if (!it) { botBusy = false; return; }
    botBusy = true;
    var log = $("#sb-log"), ty = null;
    if (botIsOpen() && log) {
      ty = document.createElement("div");
      ty.className = "sb-m sys typing";
      ty.innerHTML = '<span class="sb-tag">[ ' + esc(it[1] || "Dao") + ' ]</span><div class="sb-t"><i></i><i></i><i></i></div>';
      log.appendChild(ty); log.scrollTop = log.scrollHeight;
    }
    setTimeout(function () {
      if (ty) ty.remove();
      botPush({ who: "sys", tag: it[1] || "Dao", html: it[0], k: it[2] || "" });
      if (it[2] === "warn" || it[2] === "err") sfx.warn(); else sfx.pop();
      if (it[3]) it[3]();
      botNext();
    }, ty ? Math.min(950, 320 + it[0].length * 2) : 0);
  }
  function botSay(html, tag, kind, after) { botQ.push([html, tag, kind, after]); if (!botBusy) botNext(); }
  function botMirror(tag, html, kind) {
    if (tag === "TIP") return;
    botPush({ who: "sys", tag: tag.charAt(0) + tag.slice(1).toLowerCase(), html: html, k: kind === "err" ? "err" : kind === "warn" ? "warn" : kind === "gold" ? "gold" : "" });
  }

  var CHIPS = ["Status", "Trials", "Advice", "Realm 1", "Realm 2", "Elixirs", "Help"];
  function botChips(list) {
    var c = $("#sb-chips"); if (!c) return;
    c.innerHTML = "";
    (list || CHIPS).forEach(function (t) {
      var b = document.createElement("button");
      b.type = "button"; b.textContent = t;
      b.addEventListener("click", function () { botAsk(t); });
      c.appendChild(b);
    });
  }

  function buildBot() {
    if (botEl || !document.body) return botEl;
    botEl = document.createElement("div");
    botEl.id = "sys-bot";
    botEl.innerHTML =
      '<div class="sb-win" role="dialog" aria-label="The Heavenly Dao">' +
      '<div class="sb-head"><i class="sb-dot"></i><b>[ HEAVENLY DAO ]</b><small>AWAKE</small>' +
      '<button type="button" class="sb-clear" title="Clear log" aria-label="Clear log">⌫</button>' +
      '<button type="button" class="sb-x" aria-label="Close">✕</button></div>' +
      '<div class="sb-log" id="sb-log"></div>' +
      '<div class="sb-chips" id="sb-chips"></div>' +
      '<form class="sb-form" id="sb-form" autocomplete="off"><input id="sb-in" type="text" maxlength="120" enterkeyhint="send" autocapitalize="off" autocorrect="off" spellcheck="false" placeholder="Speak to the Dao…  (try: status)"><button type="submit" aria-label="Send">▶</button></form>' +
      "</div>";
    document.body.appendChild(botEl);
    botEl.addEventListener("click", function (e) { if (e.target === botEl) botClose(); });
    $(".sb-x", botEl).addEventListener("click", botClose);
    $(".sb-clear", botEl).addEventListener("click", function () { botSave([]); $("#sb-log").innerHTML = ""; botSay("Log cleared.", "Dao"); });
    $("#sb-form", botEl).addEventListener("submit", function (e) {
      e.preventDefault();
      var i = $("#sb-in"), v = i.value.trim();
      if (!v) return;
      i.value = "";
      botAsk(v);
    });
    botChips();
    botLoad().forEach(botRenderOne);
    return botEl;
  }
  function botOpen() {
    buildBot(); closeMenu(); closeHelp();
    botEl.classList.add("open");
    if (isPhone()) document.documentElement.classList.add("sys-lock");
    store.set("sysBotUnread", "0"); botBadge();
    var log = $("#sb-log"); if (log) log.scrollTop = log.scrollHeight;
    if (!botLoad().length) {
      botSay("The heavens have opened. I am <b>the Heavenly Dao</b>.<br>I will guide your cultivation, track your trials and answer your questions, Disciple.", "Dao");
      botSay("Say <b>help</b> to learn what I can do, or tap a button below.", "Dao");
    }
    if (window.matchMedia && matchMedia("(hover:hover)").matches) setTimeout(function () { var i = $("#sb-in"); if (i) i.focus(); }, 40);
  }
  function botClose() {
    if (botEl) botEl.classList.remove("open");
    if (!menuOpen() && !helpOpen()) document.documentElement.classList.remove("sys-lock");
  }
  function botToggle() { if (botIsOpen()) botClose(); else botOpen(); }

  /* ---- understanding commands ---- */
  var FILL = /\b(go|goto|to|open|take|me|enter|the|please|show|visit|launch|bring|into|a|my|page|on|lets|let's|i|want|need|system)\b/g;
  function findNav(q) {
    q = q.toLowerCase();
    if (/(gate|realm)\s*(1|one)\b|grakthar|first (gate|realm)/.test(q)) return "g1";
    if (/(gate|realm)\s*(2|two)\b|olympus|second (gate|realm)/.test(q)) return "g2";
    if (/\b(all gates|gates)\b/.test(q)) return "gall";
    var t = q.replace(FILL, " ").replace(/[^a-z0-9 ]/g, " ").split(/\s+/).filter(function (w) { return w.length > 1; });
    if (!t.length) return null;
    var best = null, bs = 0;
    ALLNAV.forEach(function (i) {
      var hay = (i.label + " " + i.catName + " " + (i.note || "")).toLowerCase(), sc = 0;
      t.forEach(function (w) { if (hay.indexOf(w) > -1) sc++; });
      if (sc === t.length) {
        if (sc > bs || (sc === bs && best && i.label.length < best.label.length)) { bs = sc; best = i; }
      }
    });
    return best ? best.id : null;
  }
  function statusHtml() {
    var lv = playerLevel(), rk = rankFor(lv), st = staminaInfo(), q = qRoll();
    var sp = st && st.max ? Math.round(st.cur / st.max * 100) : 0, ex = Math.floor(expPercent());
    return row("Name", esc(playerName())) + row("Level", lv) +
      row("Realm", '<span style="color:' + rk.c + '">' + (rk.r === "N" ? "SAINT" : rk.r) + " &middot; " + rk.n + "</span>") +
      row("Title", titleFor(q.streak)) +
      row("Cultivation", ex + "% " + bar(ex)) +
      row("Qi", st ? st.cur.toLocaleString() + " / " + st.max.toLocaleString() + '  ' + bar(sp) : "?") +
      row("Silver", statValue("gold") || "?") + row("Jade", statValue("gems") || "?") +
      row("Daily Cultivation", qCount(q) + " / " + QUESTS.length);
  }
  function adviceHtml() {
    var st = staminaInfo(), out = [];
    if (st && st.max) {
      var p = st.cur / st.max;
      if (p < 0.1) out.push("Your qi is nearly spent. Recommended: <b>take a stamina elixir</b> before your next realm.");
      else if (p >= 0.9) out.push("Your qi is nearly full. Spend it in a Realm &mdash; do not waste regeneration.");
    }
    var pq = pendingQuests();
    if (pq.length) out.push("Pending quest: <b>" + pq[0].name + "</b> &mdash; " + pq[0].hint + ".");
    if (expPercent() >= 90) out.push("You are <b>" + Math.floor(expPercent()) + "%</b> from a breakthrough. One more battle.");
    if (!out.length) out.push("All is in order, Disciple. Enter <b>Realm 2 &middot; Olympus</b> and grow stronger.");
    return out.join("<br>");
  }
  function greetHtml() {
    var h = new Date().getHours();
    var part = h < 5 ? "The moon is high" : h < 12 ? "Good morning" : h < 18 ? "Good afternoon" : "Good evening";
    return part + ", <b>" + esc(playerName()) + "</b>. The Heavenly Dao is at your service.";
  }
  var HELP_HTML =
    '<div class="sb-sub">Commands</div>' +
    row("status", "your cultivation record") + row("quests", "daily cultivation & streak") +
    row("advice", "what to do next") + row("realm 1 / realm 2", "enter a Secret Realm") +
    row("open &lt;page&gt;", "pouch, arena, sect…") + row("use stamina potion", "take an elixir") + row("fill mana", "refill MP with Mana Potion S") +
    row("potions", "list your elixirs") + row("session", "silver / EXP gained today") +
    row("shortcuts", "hand-seal guide") + row("mute / unmute", "Dao chimes") +
    row("chat", "open the whispers") + row("clear", "wipe this log");

  function setSetting(k, on) { store.set("sysSet_" + k, on ? "1" : "0"); applySettings(); }

  function botAsk(text) {
    var raw = String(text).trim(); if (!raw) return;
    botPush({ who: "me", html: esc(raw) });
    var q = raw.toLowerCase().replace(/[.!]+$/, "");
    botChips();

    // pending confirmation (potions)
    if (botPend && botPend.exp > Date.now()) {
      if (/^(y|yes|yep|yeah|ok|okay|sure|confirm|do it)$/.test(q)) {
        var p = botPend; botPend = null;
        botSay(p.run ? "Restoring inner qi…" : "Taking <b>" + esc(p.name) + "</b>… The page will refresh.", "Dao", "", function () { if (p.run) p.run(); else usePotion(p.c, p.name); });
        return;
      }
      if (/^(n|no|nope|cancel|stop)$/.test(q)) { botPend = null; botSay("Understood. It is cancelled.", "Dao"); return; }
    }
    botPend = null;

    if (/^(hi|hello|hey|yo|sup|good (morning|evening|afternoon))\b/.test(q)) return botSay(greetHtml(), "Dao");
    if (/(who|what) (are|r) (you|u)|your name|^(system|dao|heavenly dao)$/.test(q)) return botSay("I am <b>the Heavenly Dao</b>. I exist to help you walk the martial path. Ask, and I will answer.", "Dao");
    if (/\b(thanks|thank you|thx|ty)\b/.test(q)) return botSay("No thanks are needed. Walk on, Disciple.", "Dao");
    if (/^(yes|no|y|n)$/.test(q)) return botSay("Nothing awaits your word.", "Dao");
    if (/\b(help|commands?|what can you do)\b|^\?$/.test(q)) return botSay(HELP_HTML, "Help");
    if (/\b(status|profile|my info|who am i)\b|^me$/.test(q)) return botSay(statusHtml(), "Cultivation Record");
    if (/\b(quests?|trials?|cultivation|daily|missions?|tasks?)\b/.test(q)) return botSay(qText(), "Daily Cultivation");
    if (/\b(advice|advise|recommend|suggest|next|tips?)\b|what (should|do) i/.test(q)) return botSay(adviceHtml(), "Advice");
    if (/\b(session|progress|earned|gained)\b/.test(q)) return botSay("Today's journey:<br><b>" + esc(sessionText()) + "</b>", "Journey");
    if (/\b(time|clock)\b/.test(q)) return botSay("Heavenly hour: <b>" + esc(($("#server_time") || {}).textContent || "unknown") + "</b>.", "Dao");
    if (/\b(shortcuts?|hotkeys?|keys|keyboard)\b/.test(q)) return botSay("Opening the manual.", "Dao", "", function () { botClose(); openHelp(); });
    if (/\b(unmute|sound on)\b/.test(q)) { setSetting("sound", true); return botSay("Dao chimes <b>on</b>.", "Dao", "", sfx.ding); }
    if (/\b(mute|sound off|silence)\b/.test(q)) { setSetting("sound", false); return botSay("Dao chimes <b>off</b>.", "Dao"); }
    if (/\b(particles?)\b/.test(q)) { var po = !/off|stop|no|disable/.test(q); setSetting("particles", po); return botSay("Falling frost-petals <b>" + (po ? "on" : "off") + "</b>.", "Dao"); }
    if (/\b(scan ?lines?)\b/.test(q)) { var so = !/off|stop|no|disable/.test(q); setSetting("scan", so); return botSay("Ink-wash texture <b>" + (so ? "on" : "off") + "</b>.", "Dao"); }
    if (/\b(clear|wipe|clean)\b/.test(q)) { botSave([]); var lg = $("#sb-log"); if (lg) lg.innerHTML = ""; return botSay("Log cleared.", "Dao"); }
    if (/\b(reload|refresh)\b/.test(q)) return botSay("Refreshing…", "Dao", "", function () { location.reload(); });
    if (/^(menu|main menu)$/.test(q) || /open (the )?menu/.test(q)) return botSay("Unfurling the Martial Scroll.", "Dao", "", function () { botClose(); openMenu(); });
    if (/\b(chat|comms|messages?)\b/.test(q)) return botSay("Opening the whispers.", "Dao", "", function () { botClose(); var t = $("#gcw_toggle"); if (t) t.click(); });

    // one-click mana fill
    if (/\b(mana|mp)\b/.test(q) && /\b(use|drink|fill|refill|restore|recover|full)\b/.test(q)) {
      var mpv = readMana(), mpot = manaPotion();
      if (!mpot || mpot.q <= 0) return botSay("You have no <b>Mana Potion S</b>.", "Dao", "warn");
      if (!mpv) return botSay("I can only read your inner qi (MP) on a battle screen. Enter a battle first, Disciple.", "Dao", "warn");
      var miss = mpv.max - mpv.cur;
      if (miss <= 0) return botSay("Your inner qi (MP) is already full.", "Dao");
      var need = Math.ceil(miss / mpot.per), use = Math.min(need, mpot.q);
      botPend = { run: fillMana, name: mpot.name, exp: Date.now() + 25000 };
      botChips(["Yes", "No"]);
      return botSay("Refill MP <b>" + mpv.cur.toLocaleString() + " &rarr; " + mpv.max.toLocaleString() + "</b> using <b>" + use.toLocaleString() + "&times; " + esc(mpot.name) + "</b>?<br>Reply <b>yes</b> or <b>no</b>.", "Confirm", "warn");
    }
    // potions
    var wantsUse = /\b(use|drink|take|consume|refill|restore|heal|quaff|recover)\b/.test(q);
    var ptype = /stamina|energy|refill/.test(q) ? "stamina" : /\b(hp|health|heal|life)\b/.test(q) ? "hp" : /mana/.test(q) ? "mana" : /\bexp\b|experience/.test(q) ? "exp" : null;
    if (/potions?|elixirs?/.test(q) || (wantsUse && ptype) || /^(stamina|energy)$/.test(q)) {
      var list = potionList();
      if (!list.length) return botSay("No elixirs are within reach on this page.", "Dao", "warn");
      if (!wantsUse && !ptype) {
        var h = '<div class="sb-sub">Elixirs</div>';
        list.forEach(function (p) { h += row(esc(p.name), "x" + p.q.toLocaleString()); });
        return botSay(h + "<small>Say e.g. <b>use stamina potion</b>, or tap a slot twice on the quick-bar.</small>", "Pouch");
      }
      if (/^(stamina|energy)$/.test(q)) {
        var si = staminaInfo();
        return botSay("Qi: <b>" + (si ? si.cur.toLocaleString() + " / " + si.max.toLocaleString() : "?") + "</b>." + (si && si.max && si.cur / si.max < .3 ? "<br>Low. Say <b>use stamina potion</b>." : ""), "Dao");
      }
      var words = q.replace(/\b(use|drink|take|consume|refill|restore|heal|quaff|recover|a|an|the|one|my|potion|potions|please|stamina|energy|hp|health|mana|exp|experience|some)\b/g, " ").split(/\s+/).filter(function (w) { return w.length > 2; });
      var cand = list.filter(function (p) { return (!ptype || p.t === ptype) && p.q > 0; });
      var named = cand.filter(function (p) { return words.every(function (w) { return p.name.toLowerCase().indexOf(w) > -1; }); });
      var pick = (named.length ? named : cand)[0];
      if (!pick) return botSay("You have no usable <b>" + (ptype || "matching") + "</b> potions.", "Dao", "warn");
      botPend = { c: pick.c, name: pick.name, exp: Date.now() + 25000 };
      var others = cand.filter(function (p) { return p !== pick; }).slice(0, 3).map(function (p) { return esc(p.name) + " x" + p.q.toLocaleString(); }).join(", ");
      botChips(["Yes", "No"]);
      return botSay("Consume <b>" + esc(pick.name) + "</b> (x" + pick.q.toLocaleString() + " owned)?<br>Reply <b>yes</b> or <b>no</b>." + (others ? "<small>Other options: " + others + ". Say the full name to choose.</small>" : ""), "Confirm", "warn");
    }
    if (/^(stamina|energy|exp|gold|gems?|level|rank)$/.test(q)) return botSay(statusHtml(), "Cultivation Record");

    // travel
    var nid = findNav(q);
    if (nid) {
      var it = ALLNAV.filter(function (x) { return x.id === nid; })[0];
      return botSay("Travelling to <b>" + esc(it.label) + "</b>…", "Travel", "", function () { setTimeout(function () { goTo(nid); }, 350); });
    }

    // unknown: suggest
    var toks = q.replace(FILL, " ").split(/[^a-z0-9]+/).filter(function (w) { return w.length > 2; });
    var sug = ALLNAV.filter(function (i) { var hay = (i.label + " " + i.catName).toLowerCase(); return toks.some(function (w) { return hay.indexOf(w.slice(0, 4)) > -1; }); }).slice(0, 3);
    var msg = "I do not know that word, Disciple. Say <b>help</b> for what I understand.";
    if (sug.length) { msg += "<br>Did you mean: " + sug.map(function (i) { return "<b>" + esc(i.label) + "</b>"; }).join(", ") + "?"; botChips(sug.map(function (i) { return i.label; }).concat(["Help"])); }
    botSay(msg, "Dao", "warn");
  }

  /* ---- proactive watcher ---- */
  function proactive() {
    var st = staminaInfo(), now = Date.now();
    if (!st || !st.max) return;
    var p = st.cur / st.max;
    var lastLow = parseInt(store.get("sysWarnLow", "0"), 10) || 0;
    var lastFull = parseInt(store.get("sysWarnFull", "0"), 10) || 0;
    if (p < 0.1 && now - lastLow > 15 * 60000) {
      store.set("sysWarnLow", String(now));
      botNote("Warning", "Your qi is nearly spent (<b>" + st.cur.toLocaleString() + "</b>). Say <b>use stamina potion</b>.", "warn");
      sfx.warn();
    } else if (p >= 0.98 && now - lastFull > 60 * 60000) {
      store.set("sysWarnFull", String(now));
      botNote("Notice", "Your qi is full. Regeneration is being wasted, Disciple.", "gold");
    }
  }

  /* ---- chat unread mirror (dock 💬 badge) ---- */
  var lastUnread = 0;
  function chatBadgeSync() {
    var b = $("#gcw_badge");
    var n = 0;
    if (b && b.style.display !== "none") n = num(b.textContent);
    $$(".sys-slot.chatbtn .bdg").forEach(function (e) { e.textContent = n > 9 ? "9+" : n; e.classList.toggle("on", n > 0); });
    $$(".sys-slot.chatbtn").forEach(function (e) { e.classList.toggle("ping", n > 0); });
    if (n > lastUnread) { sfx.ding(); botNote("Whispers", "A whisper arrives &mdash; <b>" + n + "</b> unread message" + (n === 1 ? "" : "s") + ".", ""); sysLine("A new whisper has arrived."); }
    lastUnread = n;
  }
  function chatBadgeWatch() {
    var b = $("#gcw_badge");
    if (!b || b.__sysW) return;
    b.__sysW = true;
    new MutationObserver(chatBadgeSync).observe(b, { attributes: true, childList: true, characterData: true, subtree: true });
    chatBadgeSync();
  }

  /* ------------------------------------------------------------------ *
   * 9d) v4.1: potion cache, consumables panel (heal + one-click mana fill)
   * ------------------------------------------------------------------ */
  function cachePotions() {
    var cache = {};
    try { cache = JSON.parse(store.get("sysPot", "{}")) || {}; } catch (e) {}
    $$("#battleDrawer .potion-card").forEach(function (c) {
      var id = c.getAttribute("data-item-id"), inv = c.getAttribute("data-inv-id");
      if (!id || !inv) return;
      var name = (($(".potion-name span", c) || {}).textContent || "").trim();
      var q = $(".potion-qty-left", c);
      var d = (($(".potion-desc", c) || {}).textContent || "");
      var m = d.match(/Refills\s+([\d,]+)\s+Mana/i);
      cache[id] = { inv: inv, name: name, q: q ? num(q.textContent) : 0, per: m ? num(m[1]) : 0 };
    });
    store.set("sysPot", JSON.stringify(cache));
    return cache;
  }
  function manaPotion() {
    var cache = cachePotions(), best = null;
    Object.keys(cache).forEach(function (k) {
      var p = cache[k];
      if (!p.per || !/mana/i.test(p.name)) return;
      if (/mana potion s\b/i.test(p.name)) { best = p; best.pref = 1; return; }
      if (!best || (!best.pref && p.per < best.per)) best = p;   // otherwise the smallest mana potion
    });
    return best;
  }
  function readMana() {
    var re = /(\d[\d,]*)\s*\/\s*(\d[\d,]*)\s*MP\b/i;
    function skip(el) { return el && el.closest && el.closest("#sys-dock,#sys-bot,#sys-menu,#sys-help,#sys-cons,#battleDrawer"); }
    if (!document.body) return null;
    var w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null), n;
    while ((n = w.nextNode())) {
      var t = n.nodeValue;
      if (t.length > 60 || !re.test(t) || skip(n.parentElement)) continue;
      var m = t.match(re);
      return { cur: num(m[1]), max: num(m[2]) };
    }
    var cand = $$("div,span,p,small,b,strong").filter(function (e) {
      return e.children.length <= 4 && e.textContent.length < 50 && re.test(e.textContent) && !skip(e);
    })[0];
    if (cand) { var mm = cand.textContent.match(re); return { cur: num(mm[1]), max: num(mm[2]) }; }
    return null;
  }
  function btnByText(re) {
    return $$("button,a").filter(function (b) {
      return re.test(b.textContent.replace(/\s+/g, " ").trim()) && !b.closest("#sys-cons,#sys-dock,#sys-bot,#sys-menu,#sys-help,#battleDrawer,#qsDrawer,.side-drawer");
    })[0];
  }
  function healBtn() {
    return $$("button,a").filter(function (b) {
      if (b.closest("#sys-cons,#sys-dock,#sys-bot,#sys-menu,#sys-help,#battleDrawer,#qsDrawer,.side-drawer")) return false;
      return b.textContent.replace(/[^a-z ]/gi, "").trim().toLowerCase() === "heal";
    })[0];
  }
  function lca(a, b) { var p = a; while (p && !p.contains(b)) p = p.parentElement; return p; }
  function leafByText(re) {
    return $$("div,span,p,h2,h3,h4,small,b,strong,label").filter(function (e) {
      return e.children.length === 0 && re.test(e.textContent.trim()) && !e.closest("#sys-cons,#sys-bot,#sys-menu,#sys-help,#battleDrawer,#qsDrawer");
    })[0];
  }

  function manaLabel() {
    var mp = readMana(), pot = manaPotion(), small = $("#sc-mana-s"), btn = $("#sc-mana");
    if (!small || !btn) return;
    if (!mp) { small.textContent = "Restore your inner qi (MP) with one tap"; btn.disabled = false; return; }
    var miss = mp.max - mp.cur;
    if (miss <= 0) { small.textContent = "MP is full (" + mp.cur.toLocaleString() + " / " + mp.max.toLocaleString() + ")"; btn.disabled = true; return; }
    if (!pot || pot.q <= 0) { small.textContent = "No Mana Potion S found in your inventory"; btn.disabled = true; return; }
    var need = Math.ceil(miss / pot.per), use = Math.min(need, pot.q);
    small.textContent = "MP " + mp.cur.toLocaleString() + " / " + mp.max.toLocaleString() + "  →  use " + use.toLocaleString() + "× " + pot.name + (use < need ? " (all you have)" : "");
    btn.disabled = false;
  }

  function fillMana() {
    var btn = $("#sc-mana");
    var mp = readMana(), pot = manaPotion();
    if (!mp) { sysToast("Could not read your MP on this page.", "warn", 3500); return; }
    if (!pot || pot.q <= 0) { sysToast("You have no Mana Potion S.", "warn", 3500); return; }
    var miss = mp.max - mp.cur;
    if (miss <= 0) { sysToast("Your inner qi (MP) is already full.", "gold", 3000, "INNER QI"); return; }
    var need = Math.ceil(miss / pot.per), use = Math.min(need, pot.q);
    var params = new URLSearchParams();
    params.set("inv_id", pot.inv);
    if (use > 1) params.set("qty", use);
    if (btn) btn.disabled = true;
    sysLine("Restoring mana…");
    store.sset("sysMana", JSON.stringify({ name: pot.name, n: use, mp: mp.cur, t: Date.now() }));
    fetch("/use_item.php", { method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/x-www-form-urlencoded" }, body: params.toString() })
      .then(function (r) { return r.text(); })
      .then(function (raw) {
        if (/success/i.test(raw)) {
          sysToast("Consumed <b>" + use.toLocaleString() + "× " + esc(pot.name) + "</b>.<br>Refreshing…", "", 3000, "INNER QI");
          setTimeout(function () { location.reload(); }, 450);
        } else {
          store.sdel("sysMana");
          sysToast(esc((raw || "Failed to use item.").trim().slice(0, 160)), "err", 5000);
          if (btn) btn.disabled = false;
        }
      })
      .catch(function () { store.sdel("sysMana"); sysToast("Network error. Try again.", "err", 4000); if (btn) btn.disabled = false; });
  }
  function afterMana() {
    var raw = store.sget("sysMana");
    if (!raw) return;
    store.sdel("sysMana");
    try {
      var p = JSON.parse(raw);
      if (Date.now() - p.t > 20000) return;
      var mp = readMana(), msg = "Consumed <b>" + p.n.toLocaleString() + "× " + esc(p.name) + "</b>.";
      if (mp) msg += "<br>MP " + p.mp.toLocaleString() + " &rarr; <b>" + mp.cur.toLocaleString() + " / " + mp.max.toLocaleString() + "</b>";
      sysToast(msg, "", 4500, "INNER QI RESTORED");
      sysLine("Inner qi restored.");
      qMark("potion");
    } catch (e) {}
  }

  function placeConsumables() {
    if (document.hidden || !document.body) return;
    var panel = $("#sys-cons");
    var useB = btnByText(/use heal potion/i), hB = healBtn();
    if (panel && panel.isConnected) {
      // page re-rendered and produced a fresh heal row outside our panel: pull it in again
      if (useB) {
        var row0 = hB ? lca(useB, hB) : useB.parentElement;
        if (row0 && row0.textContent.length < 160 && row0 !== document.body) { var holder = $(".sc-heal", panel); holder.innerHTML = ""; holder.appendChild(row0); }
      }
      manaLabel();
      return;
    }
    if (!useB && !readMana()) return;                       // not a battle screen
    // where to put it: right under the active skills (before "Passive Skills")
    var anchor = leafByText(/^passive skills$/i), mode = "before";
    if (!anchor) {
      var act = leafByText(/^active skills$/i);
      if (act) { anchor = act.parentElement && act.parentElement.nextElementSibling ? act.parentElement.nextElementSibling : act.nextElementSibling; mode = "after"; }
    }
    if (!anchor) {
      var slash = btnByText(/^slash$/i);
      if (slash) { anchor = slash.parentElement; mode = "after"; }
    }
    if (!anchor || !anchor.parentNode) return;
    panel = document.createElement("div");
    panel.id = "sys-cons";
    panel.innerHTML =
      '<div class="sc-h">[ ELIXIR POUCH ]</div><div class="sc-body"><div class="sc-heal"></div>' +
      '<button type="button" id="sc-mana" class="sc-btn mana"><span class="sc-i">🔮</span><span><b>Use Mana Potion</b><small id="sc-mana-s">Restore your MP with one tap</small></span></button></div>';
    if (mode === "before") anchor.parentNode.insertBefore(panel, anchor);
    else anchor.parentNode.insertBefore(panel, anchor.nextSibling);
    if (useB) {
      var row = hB ? lca(useB, hB) : useB.parentElement;
      var holder2 = $(".sc-heal", panel);
      if (row && row.textContent.length < 160 && row !== document.body) holder2.appendChild(row);
      else { holder2.appendChild(useB); if (hB) holder2.appendChild(hB); }
    }
    $("#sc-mana", panel).addEventListener("click", fillMana);
    manaLabel();
    if (!store.get("sysConsTip", "")) { store.set("sysConsTip", "1"); sysToast("Heal and <b>Mana</b> buttons now sit under your skills.<br>Tap <b>Use Mana Potion</b> to refill your inner qi (MP) in one click.", "gold", 6500, "TIP"); }
  }

